"""Ten original bridge packs fill every previously unlinked graph node."""
from content_v07 import all_materials as previous_materials,entry,THEMES

def bridge(id,title,level,theme,node,body,anchor,explanation,q1,q2,word):
 p=entry('graph-'+id,title,level,theme,'story',body,[q1,q2],
  '结合本文情境复述关键决定，使用目标表达说明自己的选择，再追问一个细节。',
  '用 '+('50–80' if level=='A2' else '90–130' if level=='B1' else '140–180')+' 词写一个相似情境，使用目标句式，最后检查句式与所表达的时间或逻辑是否一致。',
  [word,('decision','决定','We need to explain our decision.'),('detail','细节','Ask for one more detail.')],['知识图谱','语境应用'],[node])
 assert anchor in body
 p['knowledge']=[{'node':node,'quote':anchor,'explanation':explanation}];return p
